import Link from "next/link";
import { prisma } from "@/lib/prisma";
import AnimatedCounter from "@/components/AnimatedCounter";
import PartnerCarousel from "@/components/PartnerCarousel";

export const dynamic = "force-dynamic";

export default async function Home() {
    const settings = await prisma.siteSetting.findMany();
    const s = settings.reduce((acc, curr) => {
        acc[curr.key] = curr.value;
        return acc;
    }, {} as Record<string, string>);

    const heroTitle = s.heroTitle || "100 ЖИЛИЙН ТҮҮХ";
    const heroSubtitle = s.heroSubtitle || "Уламжлал ба дижитал шинэчлэлийг хослуулан тэмдэглэж байна";
    const heroImage = s.heroImage || "https://images.unsplash.com/photo-1544928147-79a2dbc1f389?q=80&w=1500&auto=format&fit=crop";
    const stat1Year = s.stat1Year || "1926";
    const stat1Label = s.stat1Label || "Байгуулагдсан он";
    const stat2Number = s.stat2Number || "100+";
    const stat2Label = s.stat2Label || "Жилийн түүх";
    const stat3Year = s.stat3Year || "30,706";
    const stat3Label = s.stat3Label || "Төгсөгчид";
    const stat4Number = s.stat4Number || "386";
    const stat4Label = s.stat4Label || "Хөтөлбөр";

    const latestPosts = await prisma.post.findMany({
        where: { type: 'NEWS', published: true },
        orderBy: { createdAt: 'desc' },
        take: 3,
    });

    const featuredCamps = await prisma.camp.findMany({
        where: { isActive: true },
        orderBy: { createdAt: 'desc' },
        take: 3,
    });

    return (
        <div className="flex flex-col min-h-screen font-sans">
            {/* ===== HERO SECTION ===== */}
            <section className="relative min-h-[90vh] flex items-center overflow-hidden bg-[#0F1B3D] wave-bg">
                {/* Animated blobs */}
                <div className="absolute top-20 right-20 w-[500px] h-[500px] bg-[#1A2B5C] rounded-full opacity-60 blur-[120px] animate-blob" />
                <div className="absolute bottom-10 left-10 w-[400px] h-[400px] bg-[#243A6E] rounded-full opacity-40 blur-[100px] animate-blob animation-delay-2000" />

                {/* Wave decorative bottom */}
                <div className="absolute bottom-0 left-0 right-0 z-10">
                    <svg viewBox="0 0 1440 120" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-full" preserveAspectRatio="none">
                        <path d="M0,60 C240,120 480,0 720,60 C960,120 1200,0 1440,60 L1440,120 L0,120 Z" fill="#F5C542" fillOpacity="0.15"/>
                        <path d="M0,80 C360,120 720,40 1080,80 C1260,100 1380,60 1440,80 L1440,120 L0,120 Z" fill="#f8fafc"/>
                    </svg>
                </div>

                <div className="container relative z-20 px-4 md:px-6 mx-auto py-16 lg:py-0">
                    <div className="grid lg:grid-cols-2 gap-12 lg:gap-16 items-center">
                        {/* Left - Hero Image */}
                        <div className="relative order-2 lg:order-1 animate-fade-up">
                            <div className="relative aspect-[4/3] w-full max-w-lg mx-auto lg:max-w-none rounded-[2rem] overflow-hidden shadow-2xl shadow-black/30 border-4 border-white/10">
                                <img
                                    src={heroImage}
                                    alt="МҮЗХ 100 жил"
                                    className="w-full h-full object-cover"
                                />
                                {/* Gradient overlay */}
                                <div className="absolute inset-0 bg-gradient-to-t from-[#0F1B3D]/40 via-transparent to-transparent" />
                            </div>
                            {/* Floating accent */}
                            <div className="absolute -bottom-4 -right-4 w-24 h-24 bg-[#F5C542] rounded-2xl rotate-12 opacity-20 animate-float" />
                            <div className="absolute -top-4 -left-4 w-16 h-16 bg-[#F5C542] rounded-full opacity-15 animate-float animation-delay-1000" />
                        </div>

                        {/* Right - Content */}
                        <div className="order-1 lg:order-2 space-y-8 text-center lg:text-left animate-fade-up animation-delay-300">
                            <h1 className="text-5xl sm:text-6xl lg:text-7xl font-black text-white tracking-tight leading-[1.05]">
                                <span className="block">100 ЖИЛИЙН</span>
                                <span className="text-[#F5C542]">МҮЗХ ТҮҮХ</span>
                            </h1>
                            <div className="inline-flex items-center gap-2 bg-[#F5C542]/20 border border-[#F5C542]/30 rounded-full px-5 py-2">
                                <span className="text-sm font-bold text-[#F5C542]">{heroSubtitle}</span>
                            </div>

                            {/* Stats badges */}
                            <div className="flex flex-wrap items-center gap-4 justify-center lg:justify-start">
                                <div className="flex items-center gap-2 bg-white/10 backdrop-blur-sm rounded-full px-4 py-2 border border-white/10">
                                    <span className="text-[#F5C542]">📍</span>
                                    <span className="text-white font-bold text-sm">{stat1Year}</span>
                                    <svg className="w-4 h-4 text-white/50" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7"/></svg>
                                </div>
                                <div className="flex items-center gap-2 bg-white/10 backdrop-blur-sm rounded-full px-4 py-2 border border-white/10">
                                    <span className="text-red-400">❤️</span>
                                    <span className="text-white font-bold text-sm">{stat2Number} ЖИЛИЙН ТҮҮХ</span>
                                </div>
                            </div>

                            {/* CTA */}
                            <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
                                <Link
                                    href="/100-years"
                                    className="inline-flex h-14 items-center justify-center rounded-full bg-[#F5C542] hover:bg-[#FFD700] px-8 text-base font-bold text-[#0F1B3D] transition-all hover:scale-105 hover:shadow-lg hover:shadow-yellow-500/25"
                                >
                                    Баярт нэгдэх
                                    <svg className="w-5 h-5 ml-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                                </Link>
                                <Link
                                    href="/about"
                                    className="inline-flex h-14 items-center justify-center rounded-full border-2 border-white/20 px-8 text-base font-bold text-white hover:bg-white/10 transition-all"
                                >
                                    Бидний тухай
                                </Link>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ===== FEATURE CARDS ===== */}
            <section className="relative z-30 -mt-8 pb-20">
                <div className="container mx-auto px-4 md:px-6">
                    <div className="grid md:grid-cols-3 gap-6 max-w-6xl mx-auto">
                        {(featuredCamps.length > 0 ? featuredCamps : [
                            { id: '1', name: 'Зуны хүүхдийн зуслан', description: 'Монголын байгаль, соёлтой танилцах адал явдал.', imageUrl: 'https://images.unsplash.com/photo-1596464716127-f2a82984de30?w=600&q=80', location: '' },
                            { id: '2', name: 'Дижитал инновацийн хөтөлбөр', description: 'Ирээдүйн ур чадвараар залуучуудыг чадавхжуулах.', imageUrl: 'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=600&q=80', location: '' },
                            { id: '3', name: 'Манлайллын форум', description: 'Ирээдүйн манлайлагчдыг бий болгох.', imageUrl: 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=600&q=80', location: '' },
                        ]).map((camp: any, i: number) => (
                            <Link
                                key={camp.id}
                                href={camp.id?.length > 5 ? `/camps/${camp.id}` : '/camps'}
                                className="group relative bg-[#1A2B5C] rounded-2xl overflow-hidden shadow-xl hover:shadow-2xl transition-all duration-500 hover:-translate-y-2"
                            >
                                {/* Image */}
                                <div className="aspect-[16/10] overflow-hidden">
                                    <img
                                        src={camp.imageUrl || 'https://images.unsplash.com/photo-1478131143081-80f7f84ca84d?w=600&q=80'}
                                        alt={camp.name}
                                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110 opacity-80 group-hover:opacity-100"
                                    />
                                </div>
                                {/* Content */}
                                <div className="p-6 space-y-3">
                                    <h3 className="text-lg font-black text-white uppercase tracking-wide">{camp.name}</h3>
                                    <p className="text-white/60 text-sm font-medium line-clamp-2">
                                        {camp.description || 'Дэлгэрэнгүй мэдээллийг авна уу.'}
                                    </p>
                                    <div className="inline-flex items-center gap-2 text-[#F5C542] text-sm font-bold group-hover:gap-3 transition-all">
                                        Дэлгэрэнгүй
                                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                                    </div>
                                </div>
                            </Link>
                        ))}
                    </div>
                </div>
            </section>

            {/* ===== IMPACT / STATS SECTION ===== */}
            <section className="py-24 bg-white relative overflow-hidden">
                {/* Subtle background pattern */}
                <div className="absolute inset-0 opacity-[0.02]" style={{ backgroundImage: 'radial-gradient(#0F1B3D 1px, transparent 1px)', backgroundSize: '30px 30px' }} />

                <div className="container mx-auto px-4 md:px-6 relative z-10">
                    <div className="text-center max-w-3xl mx-auto mb-16">
                        <div className="inline-flex items-center rounded-full bg-[#0F1B3D]/5 px-4 py-1.5 text-sm font-bold text-[#0F1B3D] mb-6">
                            📊 Зууны нөлөөлөл
                        </div>
                        <h2 className="text-4xl md:text-5xl font-black text-[#0F1B3D] tracking-tight mb-6">
                            Бидний нөлөөлөл
                        </h2>
                        <p className="text-lg text-slate-500 font-medium">
                            МҮЗХ нь зуун жилийн турш олон мянган залуучуудын амьдрал, боловсролд эерэг нөлөөлж ирсэн.
                        </p>
                    </div>

                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 max-w-5xl mx-auto">
                        {[
                            { value: stat1Year, label: stat1Label, icon: '📅', color: 'bg-blue-50 border-blue-200' },
                            { value: stat3Year, label: stat3Label, icon: '👥', color: 'bg-amber-50 border-amber-200' },
                            { value: stat4Number, label: stat4Label, icon: '📋', color: 'bg-emerald-50 border-emerald-200' },
                            { value: s.stat5Number || '68,200', label: s.stat5Label || 'Зуслангийн хүүхэд', icon: '⛺', color: 'bg-purple-50 border-purple-200' },
                        ].map((stat, i) => (
                            <div key={i} className={`${stat.color} border-2 rounded-2xl p-6 md:p-8 text-center hover:shadow-lg hover:-translate-y-1 transition-all duration-300`}>
                                <div className="text-4xl mb-4">{stat.icon}</div>
                                <AnimatedCounter value={stat.value} className="text-3xl md:text-4xl font-black text-[#0F1B3D] block mb-2" />
                                <span className="text-xs md:text-sm font-bold text-slate-500 uppercase tracking-wider">{stat.label}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ===== LATEST NEWS ===== */}
            {latestPosts.length > 0 && (
                <section className="py-24 bg-slate-50">
                    <div className="container mx-auto px-4 md:px-6">
                        <div className="text-center mb-16">
                            <div className="inline-flex items-center rounded-full bg-[#0F1B3D]/5 px-4 py-1.5 text-sm font-bold text-[#0F1B3D] mb-6">
                                📰 Мэдээ мэдээлэл
                            </div>
                            <h2 className="text-4xl md:text-5xl font-black text-[#0F1B3D] tracking-tight">Сүүлийн мэдээ</h2>
                        </div>

                        <div className="grid md:grid-cols-3 gap-8 max-w-6xl mx-auto">
                            {latestPosts.map((news: any) => (
                                <Link
                                    key={news.id}
                                    href={`/news/${news.slug || news.id}`}
                                    className="group bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-2"
                                >
                                    {news.imageUrl && (
                                        <div className="aspect-video overflow-hidden bg-slate-100">
                                            <img src={news.imageUrl} alt={news.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                                        </div>
                                    )}
                                    <div className="p-6">
                                        <div className="text-xs font-bold text-[#D4A843] uppercase tracking-widest mb-3">
                                            {new Date(news.createdAt).toLocaleDateString('mn-MN', { year: 'numeric', month: 'short', day: 'numeric' })}
                                        </div>
                                        <h3 className="text-lg font-bold text-[#0F1B3D] group-hover:text-blue-600 transition-colors line-clamp-2 mb-3">{news.title}</h3>
                                        <p className="text-sm text-slate-500 line-clamp-2">
                                            {news.excerpt || news.content?.substring(0, 100).replace(/<[^>]+>/g, '')}
                                        </p>
                                    </div>
                                </Link>
                            ))}
                        </div>

                        <div className="text-center mt-12">
                            <Link href="/news" className="inline-flex items-center px-6 py-3 rounded-full border-2 border-[#0F1B3D] text-[#0F1B3D] font-bold hover:bg-[#0F1B3D] hover:text-white transition-all">
                                Бүх мэдээг үзэх
                                <svg className="w-4 h-4 ml-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3"/></svg>
                            </Link>
                        </div>
                    </div>
                </section>
            )}

            {/* ===== PARTNERS ===== */}
            <section className="bg-white py-16">
                <PartnerCarousel />
            </section>
        </div>
    );
}
